def get_rec_name(cls, records, name):
    names = {}
    classes = defaultdict(list)
    for record in records:
        record = cls.union_unshard(record.id)
        classes[record.__class__].append(record)
    for klass, records in classes.items():
        for record in klass.browse(records):
            names[cls.union_shard(record.id, klass.__name__)] = (
                record.rec_name)
    return names

def time_series(self):
    record = self.union_unshard(self.id)
    return record.time_series

def transition_start(self):
    pool = Pool()
    Country = pool.get('sale.reporting.country')
    Subdivision = pool.get('sale.reporting.country.subdivision')
    record = self.model.union_unshard(self.record.id)
    if isinstance(record, Country):
        return 'country'
    elif isinstance(record, Subdivision):
        return 'subdivision'

def _do_action(self, action):
    record = self.model.union_unshard(self.record.id)
    data = {
        'id': record.id,
        'ids': [record.id],
        }
    action['name'] += ' (%s)' % record.rec_name
    return action, data

@SuppressWarnings("unchecked")
@Override
public ActionViewBuilder createActionViewBuilder(CrmReporting crmReporting, Class<?> klass)
    throws ClassNotFoundException, AxelorException {
  if (crmReporting.getTypeSelect() != null) {
    String className = klass.getSimpleName();
    String model = null;

    boolean isPartner = crmReporting.getTypeSelect().equals(Partner.class.getName());
    boolean isOpportunity = false;

    if (className.equals(OPPORTUNITY) || className.equals(EVENT)) {

      if (isPartner) {
        model = PARTNER.toLowerCase();
      } else {
        model = LEAD;
      }

      if (className.equals(OPPORTUNITY)) {
        isOpportunity = true;
      }
    }

    String query = this.prepareQuery(crmReporting, isPartner, model);
    String idList = null;
    Query<Model> q = Query.of((Class<Model>) klass).filter(query);

    if (crmReporting.getFromDate() != null) {
      q.bind("fromDate", crmReporting.getFromDate());
    }
    if (crmReporting.getToDate() != null) {
      q.bind("toDate", crmReporting.getToDate());
    }

    idList = StringHelper.getIdListString(q.fetch());

    ActionViewBuilder actionViewBuilder = ActionView.define(I18n.get(className));
    actionViewBuilder.model(klass.getName());

    if (isOpportunity) {
      actionViewBuilder.add("kanban", className.toLowerCase() + "-kanban");
    }

    actionViewBuilder.add("grid", className.toLowerCase() + "-grid");
    actionViewBuilder.add("form", className.toLowerCase() + "-form");
    actionViewBuilder.domain(
        (!idList.isEmpty()) ? "self.id IN (" + idList + ")" : "self.id IS NULL");
    return actionViewBuilder;
  }
  throw new AxelorException(
      TraceBackRepository.CATEGORY_MISSING_FIELD,
      I18n.get(CrmExceptionMessage.CRM_REPORTING_TYPE_SELECT_MISSING));
}

@Override
public Set<Company> prefillCompanySet(CrmReporting crmReporting) {
  Set<Company> companySet = new HashSet<>();
  if (crmReporting.getCompanySet() != null) {
    companySet = crmReporting.getCompanySet();
  }
  if (AuthUtils.getUser() != null && AuthUtils.getUser().getActiveCompany() != null) {
    companySet.add(AuthUtils.getUser().getActiveCompany());
  }
  return companySet;
}

protected String prepareQuery(CrmReporting crmReporting, boolean isPartner, String model) {
  StringBuilder query = new StringBuilder();
  model = Strings.isNullOrEmpty(model) ? "" : model + ".";

  if (isPartner) {
    partnerQuery(query, crmReporting, model);
  } else {
    leadQuery(query, crmReporting, model);
  }

  if (!crmReporting.getAgencySet().isEmpty()
      && ((AppCrm) appBaseService.getApp("crm")).getAgenciesManagement())
    this.addParams(
        query,
        "self."
            + model
            + "agency.id IN ("
            + StringHelper.getIdListString(crmReporting.getAgencySet())
            + ")");

  if (!crmReporting.getIndustrySectorSet().isEmpty())
    this.addParams(
        query,
        "self."
            + model
            + "industrySector.id IN ("
            + StringHelper.getIdListString(crmReporting.getIndustrySectorSet())
            + ")");

  if (appBaseService.getAppBase().getTeamManagement() && !crmReporting.getTeamSet().isEmpty())
    this.addParams(
        query,
        "self.team.id IN (" + StringHelper.getIdListString(crmReporting.getTeamSet()) + ")");

  if (crmReporting.getFromDate() != null)
    this.addParams(query, "date(self.createdOn) >= :fromDate");

  if (crmReporting.getToDate() != null) this.addParams(query, "date(self.createdOn) <= :toDate");

  return query.toString();
}

private void partnerQuery(StringBuilder query, CrmReporting crmReporting, String model) {
  if (appBaseService.getAppBase().getEnableMultiCompany()
      && !crmReporting.getCompanySet().isEmpty())
    this.addParams(
        query,
        "(" + companyQuery("self." + model + "companySet", crmReporting.getCompanySet()) + ")");

  if (!crmReporting.getCategorySet().isEmpty())
    this.addParams(
        query,
        "self."
            + model
            + "partnerCategory.id "
            + "IN ("
            + StringHelper.getIdListString(crmReporting.getCategorySet())
            + ")");

  if (!crmReporting.getCountrySet().isEmpty())
    this.addParams(
        query,
        "self."
            + model
            + "partnerAddressList.address.country.id "
            + "IN ("
            + StringHelper.getIdListString(crmReporting.getCountrySet())
            + ")");
}

protected String companyQuery(String queryStr, Set<Company> companies) {
  return queryStr + ".id IN (" + StringHelper.getIdListString(companies) + ")";
}

protected void addParams(StringBuilder query, String paramQuery) {
  if (query.length() > 0) {
    query.append(" AND ");
  }

  query.append(paramQuery);
}

def get_columns(self):
	self.columns = [
		{
			"label": _(self.filters.tree_type),
			"options": self.filters.tree_type if self.filters.tree_type != "Order Type" else "",
			"fieldname": "entity",
			"fieldtype": "Link" if self.filters.tree_type != "Order Type" else "Data",
			"width": 140 if self.filters.tree_type != "Order Type" else 200,
		}
	]
	if self.filters.tree_type in ["Customer", "Supplier", "Item"]:
		self.columns.append(
			{
				"label": _(self.filters.tree_type + " Name"),
				"fieldname": "entity_name",
				"fieldtype": "Data",
				"width": 140,
			}
		)

	if self.filters.tree_type == "Item":
		self.columns.append(
			{
				"label": _("UOM"),
				"fieldname": "stock_uom",
				"fieldtype": "Link",
				"options": "UOM",
				"width": 100,
			}
		)

	for end_date in self.periodic_daterange:
		period = self.get_period(end_date)
		self.columns.append(
			{"label": _(period), "fieldname": scrub(period), "fieldtype": "Float", "width": 120}
		)

	self.columns.append({"label": _("Total"), "fieldname": "total", "fieldtype": "Float", "width": 120})

def get_data(self):
	if self.filters.tree_type in ["Customer", "Supplier"]:
		self.get_sales_transactions_based_on_customers_or_suppliers()
		self.get_rows()

	elif self.filters.tree_type == "Item":
		if self.filters.doc_type == "Payment Entry":
			self.data = []
			return
		self.get_sales_transactions_based_on_items()
		self.get_rows()

	elif self.filters.tree_type in ["Customer Group", "Supplier Group", "Territory"]:
		if self.filters.doc_type == "Payment Entry":
			self.data = []
			return
		self.get_sales_transactions_based_on_customer_or_territory_group()
		self.get_rows_by_group()

	elif self.filters.tree_type == "Item Group":
		if self.filters.doc_type == "Payment Entry":
			self.data = []
			return
		self.get_sales_transactions_based_on_item_group()
		self.get_rows_by_group()

	elif self.filters.tree_type == "Order Type":
		if self.filters.doc_type not in ["Quotation", "Sales Order"]:
			self.data = []
			return
		self.get_sales_transactions_based_on_order_type()
		self.get_rows_by_group()

	elif self.filters.tree_type == "Project":
		if self.filters.doc_type == "Quotation":
			self.data = []
			return
		self.get_sales_transactions_based_on_project()
		self.get_rows()

def document_filters(self):
	filters = {
		"docstatus": 1,
		"company": ["in", self.filters.company],
		self.date_field: ("between", [self.filters.from_date, self.filters.to_date]),
	}

	if self.filters.doc_type in ["Sales Invoice", "Purchase Invoice", "Payment Entry"]:
		filters["is_opening"] = "No"

	return filters

def value_field(self):
	if self.filters["value_quantity"] == "Value":
		return "base_net_total as value_field"

	return "items.stock_qty as value_field"

def _get_permitted_parent_names(self):
	return frappe.qb.get_query(
		table=self.filters.doc_type,
		fields=["name"],
		filters=self.document_filters,
		ignore_permissions=False,
	).run(pluck="name")

def get_sales_transactions_based_on_customers_or_suppliers(self):
	if self.filters.doc_type == "Payment Entry":
		self.get_payment_entries("Customer" if self.filters.tree_type == "Customer" else "Supplier")
		return

	value_field = self.value_field

	if self.filters.tree_type == "Customer":
		entity_name = "customer_name as entity_name"
		if self.filters.doc_type == "Quotation":
			entity = "party_name as entity"
		else:
			entity = "customer as entity"
	else:
		entity = "supplier as entity"
		entity_name = "supplier_name as entity_name"

	self.entries = frappe.qb.get_query(
		table=self.filters.doc_type,
		fields=[entity, entity_name, value_field, self.date_field],
		filters=self.document_filters,
		ignore_permissions=False,
	).run(as_dict=True)

	self.entity_names = {}
	for d in self.entries:
		self.entity_names.setdefault(d.entity, d.entity_name)

def get_sales_transactions_based_on_items(self):
	if self.filters["value_quantity"] == "Value":
		value_field = "base_net_amount"
	else:
		value_field = "stock_qty"

	permitted_names = self._get_permitted_parent_names()
	if not permitted_names:
		self.entries = []
		self.entity_names = {}
		return

	doctype = DocType(self.filters.doc_type)
	doctype_item = DocType(f"{self.filters.doc_type} Item")

	self.entries = (
		frappe.qb.from_(doctype_item)
		.join(doctype)
		.on(doctype.name == doctype_item.parent)
		.select(
			doctype_item.item_code.as_("entity"),
			doctype_item.item_name.as_("entity_name"),
			doctype_item.stock_uom,
			doctype_item[value_field].as_("value_field"),
			doctype[self.date_field],
		)
		.where((doctype_item.docstatus == 1) & (doctype.name.isin(permitted_names)))
	).run(as_dict=True)

	self.entity_names = {}
	for d in self.entries:
		self.entity_names.setdefault(d.entity, d.entity_name)

def get_sales_transactions_based_on_customer_or_territory_group(self):
	if self.filters.tree_type == "Customer Group":
		entity_field = "customer_group as entity"
	elif self.filters.tree_type == "Supplier Group":
		entity_field = "supplier as entity"
		self.get_supplier_parent_child_map()
	else:
		entity_field = "territory as entity"

	self.entries = frappe.qb.get_query(
		table=self.filters.doc_type,
		fields=[entity_field, self.value_field, self.date_field],
		filters=self.document_filters,
		ignore_permissions=False,
	).run(as_dict=True)
	self.get_groups()

def get_sales_transactions_based_on_project(self):
	value_field = self.value_field
	if self.filters.doc_type == "Payment Entry":
		value_field = "base_received_amount as value_field"

	entity = "project as entity"

	filters = {**self.document_filters, "project": ["!=", ""]}

	self.entries = frappe.qb.get_query(
		table=self.filters.doc_type,
		fields=[entity, value_field, self.date_field],
		filters=filters,
		ignore_permissions=False,
	).run(as_dict=True)

def filter_data_by_entities(self):
	if not self.entities:
		return

	entities = set(self.entities)
	selected_data = []
	for row in self.data:
		if row["entity"] not in entities:
			continue

		row = row.copy()
		if "indent" in row:
			row["indent"] = 0
		selected_data.append(row)

	self.data = selected_data

def get_rows(self):
	self.data = []
	self.get_periodic_data()

	for entity, period_data in self.entity_periodic_data.items():
		row = {
			"entity": entity,
			"entity_name": self.entity_names.get(entity) if hasattr(self, "entity_names") else None,
		}
		total = 0
		for end_date in self.periodic_daterange:
			period = self.get_period(end_date)
			amount = flt(period_data.get(period, 0.0))
			row[scrub(period)] = amount
			total += amount

		row["total"] = total

		if self.filters.tree_type == "Item":
			row["stock_uom"] = period_data.get("stock_uom")

		self.data.append(row)

def get_periodic_data(self):
	self.entity_periodic_data = frappe._dict()

	for d in self.entries:
		if self.filters.tree_type == "Supplier Group":
			d.entity = self.parent_child_map.get(d.entity)
		period = self.get_period(d.get(self.date_field))
		self.entity_periodic_data.setdefault(d.entity, frappe._dict()).setdefault(period, 0.0)
		self.entity_periodic_data[d.entity][period] += flt(d.value_field)

		if self.filters.tree_type == "Item":
			self.entity_periodic_data[d.entity]["stock_uom"] = d.stock_uom

def get_period(self, posting_date):
	if self.filters.range == "Weekly":
		iso_date = posting_date.isocalendar()
		period = _("Week {0} {1}").format(str(iso_date.week), str(iso_date.year))
	elif self.filters.range == "Monthly":
		period = _(str(self.months[posting_date.month - 1])) + " " + str(posting_date.year)
	elif self.filters.range == "Quarterly":
		period = _("Quarter {0} {1}").format(
			str(((posting_date.month - 1) // 3) + 1), str(posting_date.year)
		)
	else:
		year = get_fiscal_year(posting_date, company=self.filters.company[0])
		period = str(year[0])
	return period

def get_period_date_ranges(self):
	from dateutil.relativedelta import MO, relativedelta

	from_date, to_date = getdate(self.filters.from_date), getdate(self.filters.to_date)

	increment = {"Monthly": 1, "Quarterly": 3, "Half-Yearly": 6, "Yearly": 12}.get(self.filters.range, 1)

	if self.filters.range in ["Monthly", "Quarterly"]:
		from_date = from_date.replace(day=1)
	elif self.filters.range == "Yearly":
		from_date = get_fiscal_year(from_date)[1]
	else:
		from_date = from_date + relativedelta(from_date, weekday=MO(-1))

	self.periodic_daterange = []
	for _dummy in range(1, 53):
		if self.filters.range == "Weekly":
			period_end_date = add_days(from_date, 6)
		else:
			period_end_date = add_to_date(from_date, months=increment, days=-1)

		if period_end_date > to_date:
			period_end_date = to_date

		self.periodic_daterange.append(period_end_date)

		from_date = add_days(period_end_date, 1)
		if period_end_date == to_date:
			break

def get_groups(self):
	parent_field_map = {
		"Territory": "parent_territory",
		"Customer Group": "parent_customer_group",
		"Item Group": "parent_item_group",
		"Supplier Group": "parent_supplier_group",
	}
	if self.filters.tree_type not in parent_field_map:
		frappe.throw(_("Invalid Tree Type {0}").format(self.filters.tree_type))

	parent = parent_field_map[self.filters.tree_type]

	self.depth_map = frappe._dict()

	self.group_entries = frappe.db.sql(
		f"""select name, lft, rgt , {parent} as parent
		from `tab{self.filters.tree_type}` order by lft""",
		as_dict=1,
	)

	for d in self.group_entries:
		if d.parent:
			self.depth_map.setdefault(d.name, self.depth_map.get(d.parent) + 1)
		else:
			self.depth_map.setdefault(d.name, 0)

def get_teams(self):
	self.depth_map = frappe._dict()

	if not frappe.db.exists("DocType", self.filters.doc_type):
		frappe.throw(_("Invalid Document Type {0}").format(self.filters.doc_type))

	self.group_entries = frappe.db.sql(
		f""" select * from (select "Order Types" as name, 0 as lft,
		2 as rgt, '' as parent union select distinct order_type as name, 1 as lft, 1 as rgt, "Order Types" as parent
		from `tab{self.filters.doc_type}` where ifnull(order_type, '') != '') as b order by lft, name
	""",
		as_dict=1,
	)

	for d in self.group_entries:
		if d.parent:
			self.depth_map.setdefault(d.name, self.depth_map.get(d.parent) + 1)
		else:
			self.depth_map.setdefault(d.name, 0)

def get_supplier_parent_child_map(self):
	self.parent_child_map = frappe._dict(
		frappe.db.sql(""" select name, supplier_group from `tabSupplier`""")
	)

def get_chart_data(self):
	length = len(self.columns)

	if self.filters.tree_type in ["Customer", "Supplier"]:
		labels = [d.get("label") for d in self.columns[2 : length - 1]]
	elif self.filters.tree_type == "Item":
		labels = [d.get("label") for d in self.columns[3 : length - 1]]
	else:
		labels = [d.get("label") for d in self.columns[1 : length - 1]]

	datasets = []
	if self.filters.curves != "select":
		for curve in self.data:
			data = {
				"name": curve.get("entity_name", curve["entity"]),
				"values": [curve[scrub(label)] for label in labels],
			}
			if self.filters.curves == "non-zeros" and not sum(data["values"]):
				continue
			elif self.filters.curves == "total" and "indent" in curve:
				if curve["indent"] == 0:
					datasets.append(data)
			elif self.filters.curves == "total":
				if datasets:
					a = [
						data["values"][idx] + datasets[0]["values"][idx]
						for idx in range(len(data["values"]))
					]
					datasets[0]["values"] = a
				else:
					datasets.append(data)
					datasets[0]["name"] = _("Total")
			else:
				datasets.append(data)

	self.chart = {"data": {"labels": labels, "datasets": datasets}, "type": "line"}

	if self.filters["value_quantity"] == "Value":
		self.chart["fieldtype"] = "Currency"
	else:
		self.chart["fieldtype"] = "Float"

def get():
	args = get_form_params()
	with_link_titles = sbool(args.pop("with_link_titles", False))

	# If virtual doctype, get data from controller get_list method
	if is_virtual_doctype(args.doctype):
		controller = get_controller(args.doctype)
		data = compress(frappe.call(controller.get_list, args=args, **args))
	else:
		data = compress(execute(**args), args=args)

	if with_link_titles:
		send_compressed_link_titles(args, data)

	return data

def send_compressed_link_titles(args, data):
	"""Send the titles of the Link values in a `compress`ed result with the response."""
	# `compress` returns the rows untouched when there are none, and reduces a child table
	# field to its bare fieldname, so pair the requested fields back up with its key order.
	if not isinstance(data, dict):
		return
	field_info = {info.get("fieldname"): info for info in get_field_info(args.fields, args.doctype)}
	columns = [field_info.get(key) for key in data["keys"]]
	send_link_titles(get_report_link_titles(columns, data["values"]))

def get_list():
	args = get_form_params()

	if is_virtual_doctype(args.doctype):
		controller = get_controller(args.doctype)
		data = frappe.call(controller.get_list, args=args, **args)
	else:
		# uncompressed (refactored from frappe.model.db_query.get_list)
		data = execute(**args)

	return data

def validate_args(data):
	parse_json(data)
	setup_group_by(data)

	validate_fields(data)
	if data.filters:
		validate_filters(data, data.filters)
	if data.or_filters:
		validate_filters(data, data.or_filters)

	data.strict = None

	return data

def validate_fields(data):
	wildcard = update_wildcard_field_param(data)

	for field in list(data.fields or []):
		# TODO: extract_fieldnames needs to handle dict fields for qb_query aggregations
		if isinstance(field, dict):
			continue

		fieldname = extract_fieldnames(field)[0]
		if not fieldname:
			raise_invalid_field(fieldname)

		if is_standard(fieldname):
			continue

		meta, df = get_meta_and_docfield(fieldname, data)

		if not df:
			if wildcard:
				continue
			else:
				raise_invalid_field(fieldname)

		# remove the field from the query if the report hide flag is set and current view is Report
		if df.report_hide and data.view == "Report":
			data.fields.remove(field)
			continue

		if df.fieldname in [_df.fieldname for _df in meta.get_high_permlevel_fields()]:
			if df.get("permlevel") not in meta.get_permlevel_access(parenttype=data.doctype):
				data.fields.remove(field)

def validate_filters(data, filters):
	if isinstance(filters, list):
		# filters as list
		for condition in filters:
			if len(condition) == 3:
				# [fieldname, condition, value]
				fieldname = condition[0]
				if is_standard(fieldname):
					continue
				meta, df = get_meta_and_docfield(fieldname, data)
				if not df:
					raise_invalid_field(condition[0])
			else:
				# [doctype, fieldname, condition, value]
				fieldname = condition[1]
				if is_standard(fieldname):
					continue
				meta = frappe.get_meta(condition[0])
				if not meta.get_field(fieldname):
					raise_invalid_field(fieldname)

	else:
		for fieldname in filters:
			if is_standard(fieldname):
				continue
			meta, df = get_meta_and_docfield(fieldname, data)
			if not df:
				raise_invalid_field(fieldname)

def setup_group_by(data):
	"""Add columns for aggregated values e.g. count(name)"""
	if data.group_by and data.aggregate_function:
		if data.aggregate_function.lower() not in ("count", "sum", "avg"):
			frappe.throw(_("Invalid aggregate function"))

		if frappe.db.has_column(data.aggregate_on_doctype, data.aggregate_on_field):
			field = f"`tab{data.aggregate_on_doctype}`.`{data.aggregate_on_field}`"
			data.fields.append({data.aggregate_function.upper(): field, "as": "_aggregate_column"})
		else:
			raise_invalid_field(data.aggregate_on_field)

		data.pop("aggregate_on_doctype")
		data.pop("aggregate_on_field")
		data.pop("aggregate_function")

def _validate_group_by_field(raw: str, doctype: str):
	"""Validate a single `tabDoctype`.`fieldname` expression from saved report JSON."""
	if not isinstance(raw, str) or not raw:
		raise_invalid_field(raw)
	try:
		field_doctype, fieldname = parse_field(raw)
	except ValueError:
		raise_invalid_field(raw)
	field_doctype = field_doctype or doctype
	if not _FIELDNAME_RE.match(fieldname):
		raise_invalid_field(raw)
	try:
		has_col = frappe.db.has_column(field_doctype, fieldname)
	except frappe.db.TableMissingError:
		raise_invalid_field(raw)
	if not has_col:
		raise_invalid_field(raw)

def _validate_group_by_args(group_by: dict, doctype: str):
	raw_func = group_by.get("aggregate_function")
	if not isinstance(raw_func, str):
		frappe.throw(_("Invalid aggregate function: {0}").format(raw_func), frappe.DataError)
	func = raw_func.lower()
	if func not in SUPPORTED_AGGREGATE_FUNCTIONS:
		frappe.throw(_("Invalid aggregate function: {0}").format(func), frappe.DataError)

	_validate_group_by_field(group_by.get("group_by", ""), doctype)

	if func != "count":
		_validate_group_by_field(group_by.get("aggregate_on", ""), doctype)

def is_standard(fieldname):
	if "." in fieldname:
		fieldname = fieldname.split(".")[1].strip("`")
	return fieldname in default_fields or fieldname in optional_fields or fieldname in child_table_fields

def extract_fieldnames(field):
	from sql_metadata import Parser

	from frappe.database.schema import SPECIAL_CHAR_PATTERN

	if not SPECIAL_CHAR_PATTERN.findall(field):
		return [field]

	columns = Parser(f"select {field} from _dummy").columns

	if not columns:
		f = field.lower()
		if ("count(" in f or "sum(" in f or "avg(" in f) and "*" in f:
			return ["*"]

	return columns

def update_wildcard_field_param(data):
	if (isinstance(data.fields, str) and data.fields == "*") or (
		isinstance(data.fields, list | tuple) and len(data.fields) == 1 and data.fields[0] == "*"
	):
		parent_type = data.parenttype or data.parent_doctype
		data.fields = get_permitted_fields(data.doctype, parenttype=parent_type, ignore_virtual=True)
		return True

	return False

def clean_params(data):
	for param in DISALLOWED_PARAMS:
		if param in data:
			del data[param]

def parse_json(data):
	if (filters := data.get("filters")) and isinstance(filters, str):
		data["filters"] = json.loads(filters)
	if (applied_filters := data.get("applied_filters")) and isinstance(applied_filters, str):
		data["applied_filters"] = json.loads(applied_filters)
	if (or_filters := data.get("or_filters")) and isinstance(or_filters, str):
		data["or_filters"] = json.loads(or_filters)
	if (fields := data.get("fields")) and isinstance(fields, str):
		data["fields"] = ["*"] if fields == "*" else json.loads(fields)
	if isinstance(data.get("docstatus"), str):
		data["docstatus"] = json.loads(data["docstatus"])
	if isinstance(data.get("save_user_settings"), str):
		data["save_user_settings"] = json.loads(data["save_user_settings"])
	else:
		data["save_user_settings"] = True
	if isinstance(data.get("start"), str):
		data["start"] = cint(data.get("start"))
	if isinstance(data.get("page_length"), str):
		data["page_length"] = cint(data.get("page_length"))

def get_parenttype_and_fieldname(field, data):
	if "." in field:
		parts = field.split(".")
		parenttype = parts[0]
		fieldname = parts[1]
		df = frappe.get_meta(data.doctype).get_field(parenttype)
		if not df and parenttype.startswith("tab"):
			# tabChild DocType.fieldname
			parenttype = parenttype[3:]
		else:
			# tablefield.fieldname
			parenttype = df.options
	else:
		parenttype = data.doctype
		fieldname = field.strip("`")

	return parenttype, fieldname

def compress(data, args=None):
	"""separate keys and values"""
	from frappe.desk.query_report import add_total_row

	user_info = {}

	if not data:
		return data
	if args is None:
		args = {}
	values = []
	keys = list(data[0])
	for row in data:
		values.append([row.get(key) for key in keys])

		# add user info for assignments (avatar)
		if row.get("_assign", ""):
			for user in json.loads(row._assign):
				add_user_info(user, user_info)

	if args.get("add_total_row"):
		meta = frappe.get_meta(args.doctype)
		values = add_total_row(values, keys, meta)

	return {"keys": keys, "values": values, "user_info": user_info}

def save_report(name: str | int, doctype: str, report_settings: str):
	"""Save reports of type Report Builder from Report View"""

	if frappe.db.exists("Report", name):
		report = frappe.get_doc("Report", name)
		if report.is_standard == "Yes":
			frappe.throw(_("Standard Reports cannot be edited"))

		if report.report_type != "Report Builder":
			frappe.throw(_("Only reports of type Report Builder can be edited"))

		if report.owner != frappe.session.user and not report.has_permission("write"):
			frappe.throw(_("Insufficient Permissions for editing Report"), frappe.PermissionError)
	else:
		if not frappe.has_permission("Report", "create"):
			frappe.throw(_("You don't have permission to create Report records."), frappe.PermissionError)
		if not frappe.has_permission(doctype, "read"):
			frappe.throw(
				_("You don't have permission to create report for {0}").format(_(doctype)),
				frappe.PermissionError,
			)
		report = frappe.new_doc("Report")
		report.report_name = name
		report.ref_doctype = doctype

	settings = json.loads(report_settings)
	if isinstance(settings, dict) and isinstance(group_by := settings.get("group_by"), dict):
		_validate_group_by_args(group_by, report.ref_doctype)

	report.report_type = "Report Builder"
	report.json = report_settings
	report.save(ignore_permissions=True)
	frappe.msgprint(
		_("Report {0} saved").format(frappe.bold(report.name)),
		indicator="green",
		alert=True,
	)
	return report.name

def delete_report(name: str | int):
	"""Delete reports of type Report Builder from Report View"""

	report = frappe.get_doc("Report", name)
	if report.is_standard == "Yes":
		frappe.throw(_("Standard Reports cannot be deleted"))

	if report.report_type != "Report Builder":
		frappe.throw(_("Only reports of type Report Builder can be deleted"))

	if report.owner != frappe.session.user and not report.has_permission("delete"):
		frappe.throw(_("Insufficient Permissions for deleting Report"), frappe.PermissionError)

	report.delete(ignore_permissions=True)
	frappe.msgprint(
		_("Report {0} deleted").format(frappe.bold(report.name)),
		indicator="green",
		alert=True,
	)

def _export_query(form_params, csv_params, populate_response=True):
	from frappe.desk.utils import get_csv_bytes, provide_binary_file
	from frappe.utils.xlsxutils import get_default_xlsx_styles, handle_html, make_xlsx

	doctype = form_params.pop("doctype")
	owner_field = f"`tab{doctype}`.`owner`"
	if isinstance(form_params["fields"], list):
		form_params["fields"].append(owner_field)
	elif isinstance(form_params["fields"], tuple):
		form_params["fields"] = form_params["fields"] + (owner_field,)
	file_format_type = form_params.pop("file_format_type")
	title = form_params.pop("title", doctype)
	add_totals_row = 1 if form_params.pop("add_totals_row", None) == "1" else None
	translate_values = 1 if form_params.pop("translate_values", None) == "1" else None

	visible_names = form_params.pop("visible_names", None)
	if isinstance(visible_names, str):
		visible_names = frappe.parse_json(visible_names)
	if not (isinstance(visible_names, list) and visible_names):
		visible_names = None

	if selection := form_params.pop("selected_items", None):
		form_params["filters"] = {"name": ("in", json.loads(selection))}

	# visible_names is the client's ordered display sequence
	# When present, take precedence over generic filters/order/pagination: fetch
	# exactly those rows, then reorder in Python below.
	# Mirrors the visible_idx pattern in Query Report.
	if visible_names:
		form_params["filters"] = {"name": ("in", visible_names)}
		form_params["order_by"] = None
		form_params.pop("page_length", None)
		form_params.pop("limit_page_length", None)
		form_params.pop("start", None)

	make_access_log(
		doctype=doctype,
		file_type=file_format_type,
		report_name=form_params.report_name,
		filters=form_params.filters,
	)

	db_query = DatabaseQuery(doctype)
	ret = db_query.execute(**form_params)

	if visible_names:
		ret = _reorder_by_visible_names(ret, form_params.get("fields", []), doctype, visible_names)

	if not frappe.permissions.can_export(doctype):
		if frappe.permissions.can_export(doctype, is_owner=True):
			for row in ret:
				if row[-1] != frappe.session.user:
					raise frappe.PermissionError(
						_("You are not allowed to export {} doctype").format(doctype)
					)
		else:
			raise frappe.PermissionError(_("You are not allowed to export {} doctype").format(doctype))

	if add_totals_row:
		ret = append_totals_row(ret)

	fields_info = get_field_info(db_query.fields, doctype)

	labels = [info["label"] for info in fields_info]
	sr_label = _("Sr")
	data = [[sr_label, *labels]]
	processed_data = []

	if frappe.local.lang == "en" or not translate_values:
		data.extend([i + 1, *list(row)] for i, row in enumerate(ret))
	elif translate_values:
		translatable_fields = [field["translatable"] for field in fields_info]
		processed_data = []
		for i, row in enumerate(ret):
			processed_row = [i + 1] + [
				_(value) if translatable_fields[idx] else value for idx, value in enumerate(row)
			]
			processed_data.append(processed_row)
		data.extend(processed_data)

	data = handle_duration_fieldtype_values(doctype, data, db_query.fields)

	if file_format_type == "CSV":
		file_extension = "csv"
		content = get_csv_bytes(
			[[handle_html(v) if isinstance(v, str) else v for v in r] for r in data],
			csv_params,
		)
	elif file_format_type == "Excel":
		file_extension = "xlsx"

		styles = get_default_xlsx_styles(
			columns=[
				{
					"fieldname": "sr",
					"label": sr_label,
					"fieldtype": "Int",
				},
				*fields_info,
			],
			data=data[1:],  # exclude header row
			has_total_row=bool(add_totals_row),
		)

		content = make_xlsx(data, doctype, styles=styles).getvalue()

	if not populate_response:
		return title, file_extension, content

	provide_binary_file(_(title), file_extension, content)

def append_totals_row(data):
	if not data:
		return data
	data = list(data)
	totals = []
	totals.extend([""] * len(data[0]))

	for row in data:
		for i in range(len(row)):
			if isinstance(row[i], float | int):
				totals[i] = (totals[i] or 0) + row[i]

	if not isinstance(totals[0], int | float):
		totals[0] = "Total"

	data.append(totals)

	return data

def handle_duration_fieldtype_values(parent_doctype, data, fields):
	for field in fields:
		try:
			doctype, fieldname = parse_field(field)
		except ValueError:
			continue

		doctype = doctype or parent_doctype
		df = frappe.get_meta(doctype).get_field(fieldname)

		if df and df.fieldtype == "Duration":
			index = fields.index(field) + 1
			for i in range(1, len(data)):
				val_in_seconds = data[i][index]
				if val_in_seconds:
					duration_val = format_duration(val_in_seconds, df.hide_days)
					data[i][index] = duration_val
	return data

def parse_field(field: str | dict) -> tuple[str | None, str]:
	"""
	Parse a field into doctype and fieldname.

	:param field: The field string to parse.
	:returns: A tuple of (doctype, fieldname). Doctype is None if not specified.

	:raises ValueError: If the field contains aggregate functions.
	"""
	if isinstance(field, dict):  # for aggregates via qb
		raise ValueError

	key = field.split(" as ", 1)[0]

	if key.startswith(("count(", "sum(", "avg(")):
		raise ValueError

	if "." in key:
		table, column = key.split(".", 2)[:2]
		return table[4:-1], column.strip("`")

	return None, key.strip("`")

def delete_items():
	"""delete selected items"""
	import json

	items = sorted(json.loads(frappe.form_dict.get("items")), reverse=True)
	doctype = frappe.form_dict.get("doctype")

	if len(items) > 10:
		frappe.enqueue("frappe.desk.reportview.delete_bulk", doctype=doctype, items=items)
		return None

	return delete_bulk(doctype, items)

def delete_bulk(doctype, items):
	"""Delete documents one by one. Returns names that could not be deleted."""
	undeleted_items = []
	for i, d in enumerate(items):
		try:
			frappe.flags.in_bulk_delete = True
			frappe.delete_doc(doctype, d)
			if len(items) >= 5:
				frappe.publish_realtime(
					"progress",
					dict(
						progress=[i + 1, len(items)],
						title=_("Deleting {0}").format(_(doctype)),
						description=d,
					),
					user=frappe.session.user,
				)
			# Commit after successful deletion
			frappe.db.commit()
		except Exception:
			# rollback if any record failed to delete
			# if not rollbacked, queries get committed on after_request method in app.py
			undeleted_items.append(d)
			frappe.db.rollback()
	if undeleted_items and len(items) != len(undeleted_items):
		frappe.clear_messages()
		return delete_bulk(doctype, undeleted_items)
	elif undeleted_items:
		frappe.msgprint(
			_("Failed to delete {0} documents: {1}").format(len(undeleted_items), ", ".join(undeleted_items)),
			realtime=True,
			title=_("Bulk Operation Failed"),
		)
		return undeleted_items

	frappe.msgprint(
		_("Deleted {0} records from {1} doctype").format(len(items), doctype),
		realtime=True,
		title=_("Bulk Operation Successful"),
	)
	return []

def get_sidebar_stats(
	stats: str | list[str], doctype: str, filters: str | list | dict[str, Any] | None = None
):
	if filters is None:
		filters = []

	if is_virtual_doctype(doctype):
		controller = get_controller(doctype)
		args = {"stats": stats, "filters": filters}
		data = frappe.call(controller.get_stats, args=args, **args)
	else:
		data = get_stats(stats, doctype, filters)

	return {"stats": data}

def get_stats(stats: str, doctype: str, filters: str | None = None):
	"""get tag info"""
	import json

	if filters is None:
		filters = []
	columns = json.loads(stats)
	if filters:
		filters = json.loads(filters)
	results = {}

	try:
		db_columns = frappe.db.get_table_columns(doctype)
	except (frappe.db.InternalError, frappe.db.ProgrammingError):
		# raised when _user_tags column is added on the fly
		# raised if its a virtual doctype
		db_columns = []

	for column in columns:
		if column not in db_columns:
			continue
		try:
			tag_count = frappe.get_list(
				doctype,
				fields=[column, {"COUNT": "*"}],
				filters=[*filters, [column, "!=", ""]],
				group_by=column,
				as_list=True,
				distinct=1,
			)

			if column == "_user_tags":
				results[column] = scrub_user_tags(tag_count)
				no_tag_count = frappe.get_list(
					doctype,
					fields=[column, {"COUNT": "1", "as": "count"}],
					filters=[*filters, [column, "in", ("", ",")]],
					group_by=column,
					order_by=column,
				)

				no_tag_count = no_tag_count[0].get("count", 0) if no_tag_count else 0

				results[column].append([_("No Tags"), no_tag_count])
			else:
				results[column] = tag_count

		except frappe.db.SQLError:
			pass
		except frappe.db.InternalError:
			# raised when _user_tags column is added on the fly
			pass

	return results

def scrub_user_tags(tagcount):
	"""rebuild tag list for tags"""
	rdict = {}
	tagdict = dict(tagcount)
	for t in tagdict:
		if not t:
			continue
		alltags = t.split(",")
		for tag in alltags:
			if tag:
				if tag not in rdict:
					rdict[tag] = 0

				rdict[tag] += tagdict[t]

	return [[tag, rdict[tag]] for tag in rdict]

def get_match_cond(doctype, as_condition=True):
	from frappe.database.query import Engine

	engine = Engine()
	engine.get_query(doctype, db_query_compat=True)
	cond = engine.build_match_conditions(as_condition=as_condition)
	if not as_condition:
		return cond

	return ((" and (" + cond + ")") if cond else "").replace("%", "%%")

def build_match_conditions(doctype, user=None, as_condition=True):
	from frappe.database.query import Engine

	engine = Engine()
	engine.get_query(doctype, user=user, db_query_compat=True)
	match_conditions = engine.build_match_conditions(as_condition=as_condition)
	if as_condition:
		return match_conditions.replace("%", "%%")
	return match_conditions

def get_filters_cond(doctype, filters, conditions, ignore_permissions=None, with_match_conditions=False):
	if isinstance(filters, str):
		filters = json.loads(filters)

	if filters:
		flt = filters
		if isinstance(filters, dict):
			filters = filters.items()
			flt = []
			for f in filters:
				if isinstance(f[1], str) and f[1][0] == "!":
					flt.append([doctype, f[0], "!=", f[1][1:]])
				elif isinstance(f[1], list | tuple) and f[1][0].lower() in (
					"=",
					">",
					"<",
					">=",
					"<=",
					"!=",
					"like",
					"not like",
					"in",
					"not in",
					"between",
					"is",
				):
					flt.append([doctype, f[0], f[1][0], f[1][1]])
				else:
					flt.append([doctype, f[0], "=", f[1]])

		from frappe.database.query import Engine

		engine = Engine()
		engine.get_query(doctype, ignore_permissions=ignore_permissions, db_query_compat=True)

		if with_match_conditions:
			if match_cond := engine.build_match_conditions():
				conditions.append(match_cond)

		engine.build_filter_conditions(flt, conditions)

		cond = " and " + " and ".join(conditions) if conditions else ""
	else:
		cond = ""
	return cond
